# ORIGINAL: the first-boot rows of R2 (FIRSTBOOT) — `PL_initialise` + the toplevel + `halt` of pl-init.c / pl-main.c with the command lines of the
# brief, against swipl 10.1.19; `setArgvPrologFlag` (pl-prologflag.c:2857-2876) and `checkPrologFlagsAccess` (pl-prologflag.c:2968-3010, called by
# `PL_cleanup`, pl-init.c:1928).
# test/core_lang/test_firstboot_swipl.jl — on every term type:
#   * ORACLE ROWS (`_FB_ROWS`, generated between BEGIN/END GENERATED by evidence/FIRSTBOOT/gen_rows.py of the lk-channel from swipl 10.1.19, LC_ALL=C,
#     two byte-identical runs): per command line `swipl -f none -F none <args>` the exit status, the standard output of the `-g` goals and the
#     `Warning:` lines on the error stream (the halt warning of `checkPrologFlagsAccess`). The kernel side is swipl's `main()`: `PL_initialise!`, then
#     `PL_toplevel` = `query_loop('$toplevel', true)` (`prologToplevel`/`break_level` is TOP1b, not on main: the stand-in is HERE), then
#     `PL_halt(rc == 1 ? 0 : 1)` where nothing halted yet; `gd.halt_exit = false` keeps the process alive, the status read from `gd.halt_exited`.
#   * WHITE-BOX ROW: `apply_options_to_flags!` leaves `lTop` and `gTop` where it found them (the two `argv` flags are set in a foreign frame of their
#     own, as `setArgvPrologFlag` does); a leak left stale words in the local stack under the frame header that `query_loop` opens, and
#     `PL_close_query` then failed at `-g true`, `-g halt(3)` and `-p`.
#   * KNOWN DIFFERENCES (not rows): the banner (no "threaded, " with threads=false, D-0353; the version string; the help line).
#   * UNVERIFIED on the kernel when this file was written: gate decides.
# Mutation-tested by tools/mutants/FIRSTBOOT.py.
using Test, LogicKernel
const LK = LogicKernel

# TERM TYPES PER CHUNK: REFERENCE — built on the term layer; every type in CI and at milestones
include(joinpath(@__DIR__, "..", "term_under_test.jl"))
const _FB = lk_term_type(Union{Int64, Float64, String, BigInt, Rational{BigInt}})

# BEGIN GENERATED (evidence/FIRSTBOOT/gen_rows.py of the channel: swipl 10.1.19, LC_ALL=C, two byte-identical runs)
# (command line after `swipl -f none -F none`, exit status, standard output, stderr lines starting with `Warning:`)
const _FB_ROWS = Tuple{Vector{String}, Int, String, Vector{String}}[
    (["-t", "halt"], 0, "", []),
    (["-g", "true", "-t", "halt"], 0, "", []),
    (["-g", "halt(3)"], 3, "", []),
    (
        ["-D", "foo=bar", "-t", "halt"],
        0,
        "",
        [
            "Warning: [Thread main] The following Prolog flags have been set but not used:",
            "Warning: [Thread main]   foo"
        ]
    ),
    (
        ["-D", "foo=bar", "-g", "current_prolog_flag(foo,V),print(V),nl", "-t", "halt"],
        0,
        "bar\n",
        []
    ),
    (
        ["-g", "current_prolog_flag(argv,A),print(A),nl", "-t", "halt", "--", "a", "b"],
        0,
        "[a,b]\n",
        []
    ),
    (
        ["-g", "current_prolog_flag(os_argv,A),print(A),nl", "-t", "halt", "--", "a", "b"],
        0,
        "[swipl,'-f',none,'-F',none,'-g','current_prolog_flag(os_argv,A),print(A),nl','-t',halt,--,a,b]\n",
        []
    ),
    (
        ["-p", "myal=/tmp", "-g", "file_search_path(myal,X),print(X),nl", "-t", "halt"],
        0,
        "'/tmp'\n",
        []
    ),
    (
        ["-g", "aggregate_all(count,member(_,[a,b]),N),print(N),nl", "-t", "halt"],
        0,
        "2\n",
        []
    )
]
# END GENERATED

"""
A run of swipl's `main()` on `args` (the words after `swipl -f none -F none`): `(exit status, standard output, Warning: lines)`; the three
standard streams are buffers, installed before `PL_initialise!` (the `-g` goals run inside it).
"""
function _fb_run(args::Vector{String})
    gd = LK.PL_global_data{_FB}()
    gd.halt_exit = false
    ld = LK.PL_local_data{_FB}(gd)
    bufs = (IOBuffer(), IOBuffer(), IOBuffer())
    ui = LK.set_standard_stream!(ld, LK.SNO_USER_INPUT, bufs[1])
    uo = LK.set_standard_stream!(ld, LK.SNO_USER_OUTPUT, bufs[2])
    ue = LK.set_standard_stream!(ld, LK.SNO_USER_ERROR, bufs[3])
    ok = LK.PL_initialise!(gd, ld, String["swipl", "-f", "none", "-F", "none", args...])
    if ok && isempty(gd.halt_exited)
        rc = LK.query_loop(gd, ld, LK.mk_sym(_FB, Symbol("\$toplevel")), true)
        isempty(gd.halt_exited) && LK.PL_halt(gd, ld, rc == 1 ? 0 : 1)
    elseif !ok && isempty(gd.halt_exited)
        LK.PL_halt(gd, ld, 1)
    end
    LK.Sflush(uo)
    LK.Sflush(ue)
    out = String(take!(bufs[2]))
    warns = String[
        l for l in split(String(take!(bufs[3])), '\n') if startswith(l, "Warning:")
    ]
    status = length(gd.halt_exited) == 1 ? gd.halt_exited[1] : -1
    return status, out, warns
end

@testset "first boot: exit status, -g output and the halt warning against swipl 10.1.19" begin
    for (args, status, out, warns) in _FB_ROWS
        @testset "swipl -f none -F none $(join(args, ' '))" begin
            st, o, w = _fb_run(args)
            @test st == status
            @test o == out
            @test w == warns
        end
    end
end

@testset "apply_options_to_flags! leaves lTop and gTop where it found them (setArgvPrologFlag's foreign frame)" begin
    gd = LK.PL_global_data{_FB}()
    ld = LK.PL_local_data{_FB}(gd)
    gd.cmdline.os_argv = String["swipl", "-f", "none", "-F", "none", "x", "y"]
    gd.cmdline.appl_argv = String["swipl", "x", "y"]
    l0, g0 = ld.lTop, ld.gTop
    LK.apply_options_to_flags!(gd, ld)
    @test ld.lTop == l0
    @test ld.gTop == g0
end
